package com.example.smartpantrymanager;
import android.content.*;import android.database.*;import android.database.sqlite.*;import java.util.*;
public class DatabaseHelper extends SQLiteOpenHelper {
 private static final String DB="smart_pantry.db"; public DatabaseHelper(Context c){super(c,DB,null,1);}
 public void onCreate(SQLiteDatabase db){db.execSQL("CREATE TABLE ingredients(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,quantity REAL NOT NULL,unit TEXT NOT NULL,expiry_date TEXT)");db.execSQL("CREATE TABLE recipes(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,ingredients TEXT NOT NULL,steps TEXT NOT NULL)");seed(db);}
 private void seed(SQLiteDatabase db){String[][] r={{"Tomato Omelette","egg:2:pieces|tomato:1:pieces|onion:0.5:pieces","Beat eggs. Chop vegetables. Cook onion and tomato, add eggs and cook."},{"Chicken Rice","chicken:300:g|rice:200:g|onion:1:pieces","Cook rice. Cook chicken and onion thoroughly. Combine."},{"Vegetable Fried Rice","rice:300:g|egg:2:pieces|carrot:1:pieces|peas:100:g","Cook vegetables, add rice and eggs and stir-fry."},{"Pasta Tomato Sauce","pasta:250:g|tomato:2:pieces|onion:1:pieces|garlic:2:pieces","Cook pasta. Prepare tomato, onion and garlic sauce. Combine."},{"Chicken Pasta","chicken:250:g|pasta:250:g|tomato:2:pieces","Cook pasta and chicken. Add tomato and combine."},{"Tuna Sandwich","bread:2:pieces|tuna:1:can|mayonnaise:30:g","Mix tuna and mayonnaise. Place between bread slices."},{"Egg Sandwich","bread:2:pieces|egg:2:pieces|mayonnaise:20:g","Boil eggs, chop and mix with mayonnaise. Serve on bread."},{"Potato Omelette","potato:300:g|egg:3:pieces|onion:1:pieces","Cook potato and onion. Add beaten eggs and cook."},{"Chicken Soup","chicken:300:g|carrot:1:pieces|onion:1:pieces|water:500:ml","Simmer chicken and vegetables in water until cooked."},{"Vegetable Soup","carrot:2:pieces|potato:300:g|onion:1:pieces|water:500:ml","Chop vegetables and simmer until tender."},{"Bean Salad","beans:200:g|tomato:2:pieces|onion:1:pieces","Combine beans, tomato and onion."},{"Chicken Salad","chicken:200:g|lettuce:100:g|tomato:1:pieces","Cook chicken and combine with lettuce and tomato."},{"Pancakes","flour:200:g|egg:2:pieces|milk:250:ml","Mix batter and cook portions on a hot pan."},{"French Toast","bread:2:pieces|egg:2:pieces|milk:100:ml","Dip bread in egg and milk then fry."},{"Banana Pancakes","banana:2:pieces|flour:150:g|egg:1:pieces","Mash banana, mix with flour and egg, then cook."},{"Potato Hash","potato:300:g|onion:1:pieces|egg:2:pieces","Fry potato and onion then top with eggs."},{"Tomato Pasta","pasta:250:g|tomato:3:pieces|garlic:2:pieces","Cook pasta and combine with tomato and garlic."},{"Chicken Wrap","chicken:200:g|tortilla:2:pieces|lettuce:50:g","Cook chicken, place with lettuce in tortillas and roll."}};for(String[] x:r){ContentValues v=new ContentValues();v.put("name",x[0]);v.put("ingredients",x[1]);v.put("steps",x[2]);db.insert("recipes",null,v);}}
 public long insertIngredient(String n,double q,String u,String e){ContentValues v=new ContentValues();v.put("name",n);v.put("quantity",q);v.put("unit",u);v.put("expiry_date",e);return getWritableDatabase().insert("ingredients",null,v);}
 public int updateIngredient(int id,String n,double q,String u,String e){ContentValues v=new ContentValues();v.put("name",n);v.put("quantity",q);v.put("unit",u);v.put("expiry_date",e);return getWritableDatabase().update("ingredients",v,"id=?",new String[]{""+id});}
 public int deleteIngredient(int id){return getWritableDatabase().delete("ingredients","id=?",new String[]{""+id});}
 public List<Ingredient> getAllIngredients(){List<Ingredient> a=new ArrayList<>();Cursor c=getReadableDatabase().query("ingredients",null,null,null,null,null,"name ASC");while(c.moveToNext())a.add(new Ingredient(c.getInt(c.getColumnIndexOrThrow("id")),c.getString(c.getColumnIndexOrThrow("name")),c.getDouble(c.getColumnIndexOrThrow("quantity")),c.getString(c.getColumnIndexOrThrow("unit")),c.getString(c.getColumnIndexOrThrow("expiry_date"))));c.close();return a;}
 public Ingredient getIngredient(int id){Cursor c=getReadableDatabase().query("ingredients",null,"id=?",new String[]{""+id},null,null,null);Ingredient x=null;if(c.moveToFirst())x=new Ingredient(c.getInt(c.getColumnIndexOrThrow("id")),c.getString(c.getColumnIndexOrThrow("name")),c.getDouble(c.getColumnIndexOrThrow("quantity")),c.getString(c.getColumnIndexOrThrow("unit")),c.getString(c.getColumnIndexOrThrow("expiry_date")));c.close();return x;}
 public List<Recipe> getRecipes(){List<Recipe>a=new ArrayList<>();Cursor c=getReadableDatabase().query("recipes",null,null,null,null,null,"name ASC");while(c.moveToNext())a.add(new Recipe(c.getInt(c.getColumnIndexOrThrow("id")),c.getString(c.getColumnIndexOrThrow("name")),c.getString(c.getColumnIndexOrThrow("ingredients")),c.getString(c.getColumnIndexOrThrow("steps"))));c.close();return a;}
 public void onUpgrade(SQLiteDatabase db,int oldV,int newV){db.execSQL("DROP TABLE IF EXISTS ingredients");db.execSQL("DROP TABLE IF EXISTS recipes");onCreate(db);}
}
